package com.cloudpulse.entity;

import jakarta.persistence.*;
import java.time.OffsetDateTime;

/**
 * Entity representing an alert generated by a breached service rule.
 */
@Entity
@Table(name = "alerts")
public class AlertEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "service_id", nullable = false)
    private ServiceEntity service;

    @Column(name = "rule_name", nullable = false)
    private String ruleName;

    @Column(nullable = false)
    private String status; // e.g., "OPEN", "RESOLVED"

    @Column(name = "observed_value", nullable = false)
    private Double observedValue;

    @Column(name = "threshold_value", nullable = false)
    private Double thresholdValue;

    @Column(name = "created_at", nullable = false, updatable = false)
    private OffsetDateTime createdAt;

    @Column(name = "resolved_at")
    private OffsetDateTime resolvedAt;

    public AlertEntity() {}

    public AlertEntity(ServiceEntity service, String ruleName, String status, Double observedValue, Double thresholdValue) {
        this.service = service;
        this.ruleName = ruleName;
        this.status = status;
        this.observedValue = observedValue;
        this.thresholdValue = thresholdValue;
        this.createdAt = OffsetDateTime.now();
    }

    // Getters
    public Long getId() { return id; }
    public ServiceEntity getService() { return service; }
    public String getRuleName() { return ruleName; }
    public String getStatus() { return status; }
    public Double getObservedValue() { return observedValue; }
    public Double getThresholdValue() { return thresholdValue; }
    public OffsetDateTime getCreatedAt() { return createdAt; }
    public OffsetDateTime getResolvedAt() { return resolvedAt; }

    // Setters
    public void setService(ServiceEntity service) { this.service = service; }
    public void setRuleName(String ruleName) { this.ruleName = ruleName; }
    public void setStatus(String status) { this.status = status; }
    public void setObservedValue(Double observedValue) { this.observedValue = observedValue; }
    public void setThresholdValue(Double thresholdValue) { this.thresholdValue = thresholdValue; }
    public void setCreatedAt(OffsetDateTime createdAt) { this.createdAt = createdAt; }
    public void setResolvedAt(OffsetDateTime resolvedAt) { this.resolvedAt = resolvedAt; }
}